    /**
     * เพิ่มข้อความสายมู 100 ข้อความ (ไม่ทับของเดิม)
     */
    public function run(): void
    {
        $this->command->info('🌱 กำลัง seed ข้อความชวนดูดวง ชุดที่ 2 (สายมู 100 ข้อความ)...');

        $messages = $this->messages();
        $base = (int) (FortuneInviteMessage::max('sort_order') ?? 0);
        $created = 0;

        foreach ($messages as $index => $row) {
            $record = FortuneInviteMessage::firstOrCreate(
                ['message' => $row['message']],
                [
                    'category' => $row['category'],
                    'is_active' => true,
                    'sort_order' => $base + $index + 1,
                ]
            );

            if ($record->wasRecentlyCreated) {
                $created++;
            }
        }

        $this->command->info("✅ Seed ชุดที่ 2 สำเร็จ — เพิ่มใหม่ {$created} ข้อความ (คลังรวม ".FortuneInviteMessage::count().' ข้อความ)');
    }

